feed:
.rss with include.feed.
  Data: _data/pins.yml (pins), _data/pin_feeds.yml (board per feed), _data/etsy_links.yml (Etsy targets).
  Daily release: an item is published only if aktiv: true AND datum <= build date (site timezone, Europe/Berlin = same
  offset as Granada). The site rebuilds daily at 05:00 UTC, so each day's pins appear at ~06:00 Granada.
  Items stay in the feed for 30 days after their datum (Pinterest must see them at least once), then drop out.
  guid = id + datum, so a repeat of the same image on another day is a new pin.
  pubDate = datum + uhrzeit (Granada time).
  Local preview of inactive/future pins: build with an extra config containing  pins_vorschau: true
  Every  points to nidrassa.com (Etsy targets go via /etsy//), ?pin=- keeps each link unique.
{%- endcomment %}
{%- assign f = site.data.pin_feeds[include.feed] %}
{%- assign code = site.data.etsy_links._code %}
{%- assign heute = site.time | date: '%Y-%m-%d' %}
{%- assign grenze = site.time | date: '%s' | minus: 2592000 | date: '%Y-%m-%d' %}
{%- assign pins = site.data.pins | where: 'feed', include.feed | sort: 'datum' | reverse %}


    {{ f.titel | xml_escape }}
    {{ site.url }}/

    {{ f.beschreibung | xml_escape }}
    de-de
    {{ site.time | date_to_rfc822 }}
    {%- assign n = 0 %}
    {%- for pin in pins %}
    {%- if n >= 100 %}{% break %}{% endif %}
    {%- if site.pins_vorschau != true %}
      {%- unless pin.aktiv == true %}{% continue %}{% endunless %}
      {%- if pin.datum > heute or pin.datum < grenze %}{% continue %}{% endif %}
    {%- endif %}
    {%- if pin.bild == nil or pin.bild == '' or pin.titel == nil or pin.titel == '' %}{% continue %}{% endif %}
    {%- assign img = '/assets/pinterest/' | append: pin.bild %}
    {%- assign bytes = img | file_size %}
    {%- if bytes == '0' %}{% continue %}{% endif %}
    {%- assign etsy = site.data.etsy_links[pin.ziel] %}
    {%- if etsy %}
      {%- assign ziel = '/etsy/' | append: pin.ziel | append: '/' %}
      {%- capture text %}{{ pin.beschreibung | strip }} 🌿 Mit dem Code {{ code.code }} sparst du {{ code.rabatt }} im Nidrassa-Shop auf Etsy.{% endcapture %}
    {%- else %}
      {%- assign ziel = pin.ziel %}
      {%- assign text = pin.beschreibung | strip %}
    {%- endif %}
    {%- assign uid = pin.id | append: '-' | append: pin.datum %}
    {%- assign zeit = pin.datum | append: ' ' | append: pin.uhrzeit %}
    {%- assign n = n | plus: 1 %}


      {{ pin.titel | xml_escape }}
      {{ ziel | absolute_url }}?pin={{ uid | uri_escape }}
      nidrassa-pin-{{ uid | xml_escape }}
      {{ zeit | date_to_rfc822 }}
      {{ text | normalize_whitespace | xml_escape }}



    {%- endfor %}
